import { graphql, HeadProps, PageProps } from "gatsby";
import * as React from "react";

import Post, { type PostType } from "../components/post";
import SEO from "../components/seo";

interface PostListPageData {
  allMdx: { nodes: PostType[] };
}

interface PostListPageContext {
  ids: string[];
  category?: string;
  tag?: string;
}

const PostListTemplate: React.FC<
  PageProps<PostListPageData, PostListPageContext>
> = ({ data }) => {
  const {
    allMdx: { nodes: posts = [] },
  } = data;
  return (
    <ol
      className="
        mb-8 grid grid-cols-1 gap-4
        min-[2400px]:grid-cols-3
        min-[3000px]:grid-cols-4
        min-[3600px]:grid-cols-5
        min-[4200px]:grid-cols-6
        md:grid-cols-2
        lg:grid-cols-1
        xl:grid-cols-2
      "
    >
      {posts.map((post) => (
        <li key={post.fields.slug}>
          <Post post={post} size="large" showBanner />
        </li>
      ))}
    </ol>
  );
};

export const query = graphql`
  query ($ids: [String]) {
    allMdx(
      sort: { frontmatter: { date: DESC } }
      filter: { id: { in: $ids } }
    ) {
      nodes {
        excerpt(pruneLength: 200)
        fields {
          slug
        }
        frontmatter {
          banner {
            childImageSharp {
              gatsbyImageData
            }
          }
          categories
          tags
          title
          date
          updated
          timeliness
        }
      }
    }
  }
`;

export const Head = ({
  location,
  pageContext,
}: HeadProps<PostListPageData, PostListPageContext>) => {
  const { category, tag } = pageContext;
  return (
    <SEO title={category ?? tag ?? "博客列表"} pathname={location.pathname} />
  );
};

export default PostListTemplate;
